from AlgorithmImports import *
from datetime import timedelta
from collections import deque


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .Calls()
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.held_symbol = None
        self.entry_price = None
        self.entry_expiry = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.block_entries_date = None

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        local_end = bar.EndTime

        if local_end.time() < self.Time.replace(
            hour=9, minute=30, second=0, microsecond=0
        ).time():
            return

        self.fast_values.append(float(bar.Close))
        self.slow_values.append(float(bar.Close))

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = sum(list(self.fast_values)[-5:]) / 5.0
        current_slow = sum(self.slow_values) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        end_time = local_end.time()
        if (
            crossover
            and (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        ):
            self.pending_signal = True

    def OnData(self, slice):
        today = self.Time.date()

        if self.Portfolio[self.spy].Quantity != 0:
            self.HandleUnexpectedEquityPosition(today)

        if self.entry_expiry is not None and today >= self.entry_expiry:
            self.block_entries_date = today
            self.pending_signal = False

            if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration-day entry blocked")

            if self.held_symbol is not None:
                self.SubmitExit("expiration processing")

        if self.held_symbol is not None:
            if self.IsPreviousTradingDay(today, self.entry_expiry):
                if self.Time.hour > 15 or (
                    self.Time.hour == 15 and self.Time.minute >= 45
                ):
                    self.SubmitExit("expiration time stop")

            self.CheckProfitTarget(slice)

        if self.pending_signal:
            self.pending_signal = False

            if (
                self.block_entries_date == today
                or self.held_symbol is not None
                or (self.entry_ticket is not None and self.IsOpen(self.entry_ticket))
            ):
                return

            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: no current SPY bar")
            return

        spy_price = float(slice.Bars[self.spy].Close)
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def CheckProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_symbol),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag="Exit: " + reason
        )
        self.Debug("Exit submitted: {0}".format(reason))

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0 and self.entry_price is None:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_expiry = order_event.Symbol.ID.Date.date()

                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol, self.entry_price
                    )
                )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}".format(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.entry_expiry = None
                self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

        if order_event.Symbol == self.spy and order_event.FillQuantity != 0:
            self.HandleUnexpectedEquityPosition(self.Time.date())

    def HandleUnexpectedEquityPosition(self, date):
        self.block_entries_date = date
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug("Unexpected exercise or assignment; liquidating SPY")
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment")

    def IsPreviousTradingDay(self, current_date, expiry_date):
        if expiry_date is None:
            return False

        candidate = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    @staticmethod
    def IsOpen(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

