from datetime import datetime, date, time, timedelta

from QuantConnect import DataNormalizationMode, Resolution, TimeZones
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Orders import OrderStatus
from QuantConnect.Securities.Option import OptionRight


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._minute_bars = {}
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None
        self._spy_cleanup_ticket = None

    def OnData(self, slice):
        self._handle_unexpected_spy_position()

        if self._blocked_entry_date == self.Time.date():
            self._process_expiration_state()
            return

        self._process_expiration_state()

        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            self._evaluate_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar, slice):
        bar_time = bar.Time
        local_date = bar_time.date()
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minutes_from_open = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        bucket_start_minute = (minutes_from_open // 5) * 5
        bucket_start = datetime.combine(
            local_date,
            time(9, 30)
        ) + timedelta(minutes=bucket_start_minute)
        bucket_end = bucket_start + timedelta(minutes=5)

        bucket = self._minute_bars.setdefault(
            bucket_start,
            {
                "bars": {},
                "open": bar.Open,
                "high": bar.High,
                "low": bar.Low,
                "close": bar.Close,
                "volume": bar.Volume
            }
        )

        minute_key = bar_time.replace(second=0, microsecond=0)
        bucket["bars"][minute_key] = bar
        bucket["open"] = min(bucket["open"], bar.Open) if False else bucket["open"]
        bucket["high"] = max(bucket["high"], bar.High)
        bucket["low"] = min(bucket["low"], bar.Low)
        bucket["close"] = bar.Close
        bucket["volume"] += bar.Volume

        if local_time.minute % 5 != 4:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(expected_time in bucket["bars"] for expected_time in expected_times):
            self._minute_bars.pop(bucket_start, None)
            return

        self._minute_bars.pop(bucket_start, None)
        self._process_consolidated_bar(bucket_end, bucket["close"], slice)

        stale_keys = [
            key for key in self._minute_bars
            if key < bucket_start
        ]
        for key in stale_keys:
            self._minute_bars.pop(key, None)

    def _process_consolidated_bar(self, end_time, close, slice):
        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if not eligible_time:
            return

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_crossover = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_crossover:
            self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        current_date = self.Time.date()

        if self._blocked_entry_date == current_date:
            return

        if self._entry_ticket is not None and self._is_order_open(self._entry_ticket):
            return

        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _evaluate_exit(self, slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        if not self.Portfolio[self._held_symbol].Invested:
            return

        if self._exit_ticket is not None and self._is_order_open(self._exit_ticket):
            return

        quote = None
        if self._held_symbol in slice.QuoteBars:
            quote = slice.QuoteBars[self._held_symbol]

        if quote is None or quote.Bid is None or quote.Ask is None:
            midpoint = None
        else:
            bid = quote.Bid.Close
            ask = quote.Ask.Close
            midpoint = (bid + ask) / 2 if bid > 0 and ask > 0 else None

        if midpoint is not None and midpoint >= self._entry_price * 1.5:
            self._submit_exit("50% profit target")
            return

        expiry_date = self._held_symbol.ID.Date.date()
        if (
            self.Time.time() >= time(15, 45)
            and self.Time.date() == self._immediately_preceding_trading_day(expiry_date)
        ):
            self._submit_exit("expiration time stop")

    def _process_expiration_state(self):
        if self._held_symbol is None:
            return

        expiry_date = self._held_symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self._blocked_entry_date = self.Time.date()

            if self._entry_ticket is not None and self._is_order_open(self._entry_ticket):
                self._entry_ticket.Cancel("Expiration processing")

            if self.Portfolio[self._held_symbol].Invested:
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_ticket is not None and self._is_order_open(self._exit_ticket):
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(order_event.Symbol))
            self._exit_ticket = None
            self._held_symbol = None
            self._entry_price = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment")
            self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if (
            self._spy_cleanup_ticket is not None
            and self._is_order_open(self._spy_cleanup_ticket)
        ):
            return

        self.Debug("Unexpected SPY equity position; liquidating")
        self._spy_cleanup_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment cleanup"
        )
        self._blocked_entry_date = self.Time.date()

    def _immediately_preceding_trading_day(self, target_date):
        check_date = target_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(check_date, time.min)
        ):
            check_date -= timedelta(days=1)

        return check_date

    def _is_order_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

