        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )
        self.option = option
        self.option_canonical = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.no_entry_date = None
        self.equity_liquidation_submitted = False

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime
        local_time = end_time.time()

        if end_time.hour < 9 or end_time.hour > 16:
            return

        if end_time.hour == 9 and end_time.minute < 35:
            return

        if end_time.hour == 16 and end_time.minute > 0:
            return

        if end_time.minute % 5 != 0:
            return

        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end_time, bar.Close)
        self.slow.Update(end_time, bar.Close)

        if old_fast is None or old_slow is None:
            return

        if (
            end_time.hour > 9 or
            (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or
            (end_time.hour == 14 and end_time.minute <= 30)
        ):
            if old_fast <= old_slow and self.fast.Current.Value > self.slow.Current.Value:
                self.pending_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_symbol is not None:
            self.HandleExpirationSafety(slice)
            self.HandleHeldOptionExit(slice)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        if not slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        chain = self.GetCurrentOptionChain(slice)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = slice.Bars[self.spy].Close
        minimum_strike = current_price * 1.01

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for contract in chain.Contracts.Values:
            expiry = contract.Expiry.date()

            if expiry < minimum_expiry:
                continue

            if contract.Right != OptionRight.Call:
                continue

            if contract.Strike < minimum_strike:
                continue

            contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        contracts.sort(key=lambda c: (c.Expiry.date(), c.Strike, str(c.Symbol)))
        selected = contracts[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish crossover call entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def HandleHeldOptionExit(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if (
            self.IsImmediatelyPrecedingTradingDay(today, expiry_date) and
            self.Time.hour == 15 and
            self.Time.minute >= 45
        ):
            self.SubmitExit("Expiration time stop")
            return

        contract = self.GetHeldContract(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def HandleExpirationSafety(self, slice):
        if self.held_symbol is None:
            return

        if self.Time.date() >= self.held_symbol.ID.Date.date():
            self.no_entry_date = self.Time.date()
            self.SubmitExit("Expiration safety liquidation")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )

        self.Debug("Exit submitted: {0} ({1})".format(self.held_symbol, reason))

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Submitted
            ):
                if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0 and not self.equity_liquidation_submitted:
            self.Debug(
                "Unexpected exercise or assignment handling: liquidating SPY equity."
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.equity_liquidation_submitted = True

        if quantity == 0:
            self.equity_liquidation_submitted = False

    def GetCurrentOptionChain(self, slice):
        if slice.OptionChains is None:
            return None

        if slice.OptionChains.ContainsKey(self.option_canonical):
            return slice.OptionChains[self.option_canonical]

        for chain in slice.OptionChains.Values:
            if chain.Symbol == self.option_canonical:
                return chain

        return None

    def GetHeldContract(self, slice):
        if slice.OptionChains is None:
            return None

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_symbol:
                    return contract

        return None

    def IsImmediatelyPrecedingTradingDay(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate > current_date:
            if self.IsTradingDay(candidate):
                return False
            candidate -= timedelta(days=1)

        return candidate == current_date

    def IsTradingDay(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        date_time = datetime(date_value.year, date_value.month, date_value.day)
        return exchange_hours.IsDateOpen(date_time)

    def IsOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

