        if slice.OptionChains is None:
            return None

        if slice.OptionChains.ContainsKey(self.option_canonical):
            return slice.OptionChains[self.option_canonical]

        for chain in slice.OptionChains.Values:
            if chain.Symbol == self.option_canonical:
                return chain

        return None

    def GetHeldContract(self, slice):
        if slice.OptionChains is None:
            return None

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_symbol:
                    return contract

        return None

    def IsImmediatelyPrecedingTradingDay(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate > current_date:
            if self.IsTradingDay(candidate):
                return False
            candidate -= timedelta(days=1)

        return candidate == current_date

    def IsTradingDay(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        date_time = datetime(date_value.year, date_value.month, date_value.day)
        return exchange_hours.IsDateOpen(date_time)

    def IsOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

