            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.close_history = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.blocked_entry_date = None
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        self._handle_assignment_and_equity(slice)
        self._handle_expiration_processing()
        self._handle_time_stop(slice)
        self._handle_profit_target(slice)

        if self.blocked_entry_date == self.Time.date():
            return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_start = self._to_new_york(bar.Time)
        local_end = self._to_new_york(bar.EndTime)

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        endpoint = local_end.replace(second=0, microsecond=0)
        minute = endpoint.minute
        endpoint += timedelta(minutes=(5 - minute % 5) % 5)

        if self.bucket_end is not None and endpoint != self.bucket_end:
            self._finalize_bucket(slice)

        if self.bucket_end != endpoint:
            self.bucket_end = endpoint
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        bars = list(self.bucket_bars)
        endpoint = self.bucket_end

        self.bucket_end = None
        self.bucket_bars = []

        if len(bars) != 5:
            return

        bars.sort(key=lambda b: b.Time)
        starts = [self._to_new_york(b.Time) for b in bars]

        for index in range(1, len(starts)):
            if starts[index] - starts[index - 1] != timedelta(minutes=1):
                return

        expected_start = endpoint - timedelta(minutes=5)
        if starts[0] != expected_start:
            return

        close = bars[-1].Close
        self.close_history.append(close)

        if len(self.close_history) < self.slow_period:
            return

        fast = sum(list(self.close_history)[-self.fast_period:]) / self.fast_period
        slow = sum(self.close_history) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if (
            bullish_cross and
            time(9, 45) <= endpoint.time() <= time(14, 30)
        ):
            self._try_entry(slice, close, endpoint)

    def _try_entry(self, slice: Slice, spy_price: float, bar_end: datetime):
        if spy_price <= 0 or self._entry_order_open() or self._option_position_exists():
            return

        chain = self._get_option_chain(slice)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

