                if candidate.Symbol == self.entry_symbol:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _handle_time_stop(self, slice: Slice):
        if self.entry_symbol is None or not self._option_position_exists():
            return

        expiry = self.Securities[self.entry_symbol].Symbol.ID.Date
        if expiry is None:
            return

        expiry_date = expiry.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _handle_expiration_processing(self):
        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            if self._option_position_exists():
                self._submit_exit("expiration liquidation")
                self.Debug("Unexpected option position during expiration processing.")

    def _submit_exit(self, reason: str):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order.")

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {0}.".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0} at {1}.".format(
                        self.entry_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}.".format(order_event.Symbol))
                self.entry_symbol = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected exercise or assignment detected.")
            self.blocked_entry_date = self.Time.date()

    def _handle_assignment_and_equity(self, slice: Slice):
        if self.Portfolio[self.spy].Quantity != 0:
            if not self.equity_liquidation_submitted:
                self.Debug("Unexpected SPY equity position; liquidating immediately.")
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Unexpected exercise or assignment handling"
                )
                self.equity_liquidation_submitted = True
        else:
            self.equity_liquidation_submitted = False

    def _get_option_chain(self, slice: Slice):
        if slice.OptionChains is None:
            return None

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            return chain

        for candidate in slice.OptionChains.Values:
            return candidate

        return None

    def _option_position_exists(self):
        return (
            self.entry_symbol is not None and
            self.Portfolio[self.entry_symbol].Quantity > 0
        )

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None and
            self._ticket_is_open(self.entry_ticket)
        )

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while True:
            candidate_dt = datetime(
                candidate.year, candidate.month, candidate.day
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate_dt):
                return candidate
            candidate -= timedelta(days=1)

    def _to_new_york(self, value):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.astimezone(self.TimeZone)

