from collections import deque
from datetime import timedelta


class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.blocked_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_expiration()
        self._process_option_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        completed_bar = self._add_minute_bar(bar)

        if completed_bar is None:
            return

        self._evaluate_crossover_entry(completed_bar, slice)

    def _add_minute_bar(self, bar):
        end = bar.EndTime
        minute_start = end - timedelta(minutes=1)
        bucket_end = (
            minute_start.replace(second=0, microsecond=0)
            + timedelta(minutes=5 - minute_start.minute % 5)
        )

        if self.bucket_end is None:
            self.bucket_end = bucket_end
            self.bucket_bars = [bar]
            return None

        if bucket_end != self.bucket_end:
            completed = None

            if len(self.bucket_bars) == 5:
                ends = [b.EndTime for b in self.bucket_bars]
                consecutive = all(
                    ends[i] - ends[i - 1] == timedelta(minutes=1)
                    for i in range(1, len(ends))
                )

                if consecutive:
                    first = self.bucket_bars[0]
                    last = self.bucket_bars[-1]
                    completed = TradeBar(
                        self.bucket_end - timedelta(minutes=5),
                        self.spy,
                        first.Open,
                        max(b.High for b in self.bucket_bars),
                        min(b.Low for b in self.bucket_bars),
                        last.Close,
                        sum(b.Volume for b in self.bucket_bars),
                        timedelta(minutes=5)
                    )

            self.bucket_end = bucket_end
            self.bucket_bars = [bar]
            return completed

        self.bucket_bars.append(bar)
        return None

    def _evaluate_crossover_entry(self, bar, slice):
        bar_time = bar.EndTime.time()

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self.blocked_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_is_open():
            return

        self.fast_window.append(bar.Close)
        self.slow_window.append(bar.Close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        current_fast = sum(self.fast_window) / 5.0
        current_slow = sum(self.slow_window) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish:
            return

        self._submit_entry(slice, bar.Close)

    def _submit_entry(self, slice, spy_price):
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        contracts = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no call contracts.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        selected_expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}".format(
                selected.Symbol,
                selected.Strike,
                selected_expiration
            )
        )

    def _process_option_exit(self, slice):
        if self.held_symbol is None:
            return

        quantity = int(self.Portfolio[self.held_symbol].Quantity)
        if quantity <= 0:
            return

