from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.spy_symbol = self.spy.Symbol
        self.option_symbol = self.option.Symbol

        self.closes = deque(maxlen=20)
        self.current_bucket_end = None
        self.current_bucket_bars = {}

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_option = None
        self.entry_price = None
        self.expiry_date = None
        self.previous_expiry_trading_day = None
        self.no_entry_date = None
        self.equity_liquidation_submitted = False

    def OnData(self, data: Slice):
        self._handle_unexpected_equity_position()

        if self.held_option is not None:
            self._evaluate_exit(data)

            if self.Portfolio[self.held_option].Quantity <= 0:
                self._clear_position_state()

        spy_bar = data.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, data)

    def _process_minute_bar(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime
        if end_time.date() != self.Time.date():
            return

        end_minutes = end_time.hour * 60 + end_time.minute
        if end_minutes < 9 * 60 + 31 or end_minutes > 16 * 60:
            return

        bucket_end_minutes = ((end_minutes - 1) // 5 + 1) * 5
        bucket_end = end_time.replace(
            hour=bucket_end_minutes // 60,
            minute=bucket_end_minutes % 60,
            second=0,
            microsecond=0,
        )

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.current_bucket_bars = {}

        self.current_bucket_bars[end_time] = bar

        if len(self.current_bucket_bars) != 5:
            return

        minute_bars = sorted(self.current_bucket_bars.values(), key=lambda x: x.EndTime)
        if [x.EndTime for x in minute_bars] != [
            bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)
        ]:
            self.current_bucket_bars = {}
            return

        consolidated_close = minute_bars[-1].Close
        self._process_five_minute_close(
            consolidated_close, bucket_end, data
        )

        self.current_bucket_bars = {}

    def _process_five_minute_close(self, close: float, bar_end, data: Slice):
        prior_fast = None
        prior_slow = None

        if len(self.closes) >= 20:
            prior_fast = sum(list(self.closes)[-5:]) / 5.0
            prior_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20 or prior_fast is None or prior_slow is None:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_crossover = (
            prior_fast <= prior_slow
            and current_fast > current_slow
        )

        bar_time = bar_end.time()
        eligible_time = (
            timedelta(hours=9, minutes=45) <=
            timedelta(
                hours=bar_time.hour,
                minutes=bar_time.minute,
                seconds=bar_time.second
            ) <=
            timedelta(hours=14, minutes=30)
        )

        if bullish_crossover and eligible_time:
            self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self.entry_order_id is not None:
            return

        if self.held_option is not None:
            return

        if self.no_entry_date == self.Time.date():
            return

        chains = []
        for chain in data.OptionChains.Values:
            if chain.Symbol == self.option_symbol:
                chains.append(chain)

        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        candidates = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying expiration or call.")
            return

        nearest_expiry = min(c.Expiry.date() for c in candidates)
        strike_floor = 1.01 * spy_price

        strike_candidates = [
            c for c in candidates
            if c.Expiry.date() == nearest_expiry
            and c.Strike >= strike_floor
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_order_id = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        ).OrderId

        self.Debug(
            "Entry submitted: {} strike {} expiry {}.".format(
                selected.Symbol,
                selected.Strike,
                nearest_expiry
            )
        )

    def _evaluate_exit(self, data: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        held_quantity = self.Portfolio[self.held_option].Quantity
        if held_quantity <= 0:
            return

        expiry_date = self.expiry_date
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("Expiration-day liquidation")
            return

        if (
            self.previous_expiry_trading_day == today
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self.exit_order_id is not None:
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_order_id is not None:
            existing = self.Transactions.GetOrderById(self.exit_order_id)
            if existing is not None and existing.Status.IsOpen():
                existing_ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
                if existing_ticket is not None:
                    existing_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted: {}.".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiry_date = self.Securities[
                    self.held_option
                ].Symbol.ID.Date.date()

                self.previous_expiry_trading_day = (
                    self._get_previous_trading_day(self.expiry_date)
                )

                self.entry_order_id = None
                self.Debug(
                    "Entry filled: {} at {:.4f}.".format(
                        self.held_option,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled,
            ):
                if order_event.Status != OrderStatus.PartiallyFilled:
                    self.entry_order_id = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}.".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_order_id = None
                self._clear_position_state()
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_order_id = None

    def _get_previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            candidate
        ):
            candidate -= timedelta(days=1)
        return candidate

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy_symbol].Quantity > 0:
            if not self.equity_liquidation_submitted:
                self.Debug(
                    "Unexpected exercise or assignment: liquidating SPY equity."
                )
                self.MarketOrder(
                    self.spy_symbol,
                    -self.Portfolio[self.spy_symbol].Quantity,
                    tag="Unexpected exercise or assignment"
                )
                self.equity_liquidation_submitted = True
        else:
            self.equity_liquidation_submitted = False

    def _clear_position_state(self):
        self.held_option = None
        self.entry_price = None
        self.expiry_date = None
        self.previous_expiry_trading_day = None
        self.exit_order_id = None

