from AlgorithmImports import *


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

        self._bucket_key = None
        self._bucket_bars = []

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Immediately remove any unexpected SPY equity position.
        if self.Portfolio[self.spy].Quantity != 0:
            quantity = -self.Portfolio[self.spy].Quantity
            self.Debug("Unexpected SPY exercise/assignment; liquidating equity.")
            self.MarketOrder(self.spy, quantity)

        # Process expiration and minute-level exits before considering entries.
        if self.held_option is not None:
            held = self.Portfolio[self.held_option]

            if held.Quantity == 0:
                self._clear_option_state()
            else:
                expiration_date = self.held_option.ID.Date.date()

                if today >= expiration_date:
                    self.no_entry_date = today
                    self._submit_exit("expiration processing")
                else:
                    previous_trading_day = self._previous_trading_day(
                        expiration_date
                    )

                    if (
                        today == previous_trading_day
                        and self.Time.hour == 15
                        and self.Time.minute >= 45
                    ):
                        self._submit_exit("expiration time stop")
                    else:
                        self._check_profit_target(slice)

        # Build a five-minute bar from actual minute bars only.
        minute_bar = slice.Bars.get(self.spy)
        if minute_bar is not None:
            self._update_five_minute_bar(minute_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_time = self.Time.replace(second=0, microsecond=0)

        if local_time.hour < 9 or local_time.hour > 15:
            return
        if local_time.hour == 9 and local_time.minute < 30:
            return

        bucket_start_minute = local_time.minute - (local_time.minute % 5)
        bucket_key = local_time.replace(minute=bucket_start_minute)

        if self._bucket_key is None:
            self._bucket_key = bucket_key

        if bucket_key != self._bucket_key:
            if len(self._bucket_bars) == 5:
                consolidated = self._consolidate(self._bucket_bars)
                self._on_five_minute_bar(consolidated, slice)

            self._bucket_key = bucket_key
            self._bucket_bars = []

        self._bucket_bars.append(minute_bar)

    def _consolidate(self, bars):
        first = bars[0]
        last = bars[-1]

        return TradeBar(
            first.Time,
            self.spy,
            first.Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            last.Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(self.fast_period)) / self.fast_period
        slow = sum(self.closes[i] for i in range(self.slow_period)) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        bar_end = self._bucket_key + timedelta(minutes=5)
        eligible_time = (
            bar_end.hour > 9 or
            (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or
            (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish_cross and eligible_time:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.no_entry_date == today:
            return
        if self.held_option is not None:
            return
        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration.")
            return

        expiry = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price
        candidates = [
            contract
            for contract in chain.Contracts.Values
            if (
                contract.Expiry.date() == expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return
        if self.entry_price is None or self.held_option is None:
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -holding.Quantity
        )
        self.no_entry_date = self.Time.date()
        self.Debug("Option exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_option = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                "Call entry filled: "
                + str(self.held_option)
                + " @ "
                + str(self.entry_price)
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call exit filled: " + str(order_event.Symbol))
            self._clear_option_state()

        if (
            order_event.Symbol.SecurityType == SecurityType.Equity
            and order_event.Symbol == self.spy
        ):
            message = str(order_event.Message).lower()
            if "assign" in message or "exercis" in message:
                quantity = self.Portfolio[self.spy].Quantity
                if quantity != 0:
                    self.Debug("Unexpected exercise/assignment event; liquidating SPY.")
                    self.MarketOrder(self.spy, -quantity)

    def _clear_option_state(self):
        self.held_option = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        while date_value.weekday() >= 5:
            date_value -= timedelta(days=1)
        return date_value

