        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_open = True
        self.Debug(f"Exit submitted: {reason}")

    def _entry_is_blocked(self) -> bool:
        if self.entry_order_open:
            return True

        if self.held_symbol is not None:
            return True

        return False

    def _is_immediately_preceding_trading_day(
        self,
