        expiry_date
    ) -> bool:
        if current_date >= expiry_date:
            return False

        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        candidate = current_date + timedelta(days=1)

        while candidate < expiry_date:
            if exchange_hours.IsDateOpen(candidate):
                return False
            candidate += timedelta(days=1)

        return exchange_hours.IsDateOpen(current_date)

