from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_canonical = option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_dates = set()

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(current_date)
        self._evaluate_exit(slice, current_date)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated = self._update_five_minute_bar(spy_bar)
        if consolidated is None:
            return

        close_price, bar_end = consolidated
        self._evaluate_crossover_and_enter(slice, close_price, bar_end)

    def _update_five_minute_bar(self, bar: TradeBar):
        bar_end = bar.EndTime.astimezone(self.TimeZone).replace(
            second=0,
            microsecond=0
        )

        if bar_end.hour < 9 or (
            bar_end.hour == 9 and bar_end.minute < 31
        ) or bar_end.hour > 16:
            return None

        if bar_end.hour == 16 and bar_end.minute > 0:
            return None

        total_minutes = bar_end.hour * 60 + bar_end.minute
        bucket_index = (total_minutes - 570) // 5
        new_bucket_end = bar_end.replace(
            hour=0,
            minute=0
        ) + timedelta(minutes=570 + (bucket_index + 1) * 5)

        emitted = None

        if self.bucket_end is not None and new_bucket_end != self.bucket_end:
            emitted = self._complete_bucket()
            self.bucket_bars = {}

        if self.bucket_end is None or new_bucket_end != self.bucket_end:
            self.bucket_end = new_bucket_end

        self.bucket_bars[bar_end] = bar.Close
        return emitted

    def _complete_bucket(self):
        if self.bucket_end is None:
            return None

        expected = {
            self.bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        }

        if set(self.bucket_bars.keys()) != expected:
            return None

        close_price = self.bucket_bars[
            self.bucket_end - timedelta(minutes=1)
        ]

        return close_price, self.bucket_end

    def _evaluate_crossover_and_enter(self, slice: Slice, price: float, bar_end):
        if bar_end.time() < datetime.strptime("09:45", "%H:%M").time():
            return

        if bar_end.time() > datetime.strptime("14:30", "%H:%M").time():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_closed(self.entry_ticket):
            return

        previous_ready = len(self.closes) >= 20
        if previous_ready:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(price)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_ready
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross:
            self._try_enter(slice, price)

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()
        if today in self.no_entry_dates:
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiration = today + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiration_date = contract.Expiry.date()
                if expiration_date < minimum_expiration:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiration
        ]

        selected = min(
            candidates,
