class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = deque(maxlen=5)
        self.slow = deque(maxlen=20)
        self.fast_sum = 0.0
        self.slow_sum = 0.0
        self.previous_fast = None
        self.previous_slow = None

        self.builder = FiveMinuteBarBuilder(
            self.spy.Symbol,
            self.OnFiveMinuteBar
        )

        self.pending_signal = None
        self.entry_order = None
        self.exit_order = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing(current_date)

        if self.spy.Symbol in slice.Bars:
            self.builder.update(slice.Bars[self.spy.Symbol])

        if self.pending_signal is not None:
            signal_time = self.pending_signal
            self.pending_signal = None

            if self.no_entry_date == current_date:
                return

            if self.entry_order is not None or self.HasOptionHolding():
                return

            self.TryEnter(slice, signal_time)

        if self.HasOptionHolding():
            self.EvaluateProfitTarget(slice)
            self.EvaluateTimeStop()

    def OnFiveMinuteBar(self, bar):
        close = float(bar.Close)

        if len(self.fast) == self.fast.maxlen:
            self.fast_sum -= self.fast[0]
        self.fast.append(close)
        self.fast_sum += close

        if len(self.slow) == self.slow.maxlen:
            self.slow_sum -= self.slow[0]
        self.slow.append(close)
        self.slow_sum += close

        current_fast = None
        current_slow = None

        if len(self.fast) == self.fast.maxlen:
            current_fast = self.fast_sum / len(self.fast)
        if len(self.slow) == self.slow.maxlen:
            current_slow = self.slow_sum / len(self.slow)

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        ):
            bar_end = bar.EndTime.time()
            if time(9, 45) <= bar_end <= time(14, 30):
                self.pending_signal = bar.EndTime

        if current_fast is not None and current_slow is not None:
            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def TryEnter(self, slice, signal_time):
        chain = self.GetCurrentOptionChain(slice)

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiry = expiries[0]
        current_price = float(self.Securities[self.spy.Symbol].Price)

        if current_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = current_price * 1.01
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        contract = candidates[0]

        self.held_option = contract.Symbol
        self.entry_price = None
        self.entry_order = None

        self.entry_order = self.MarketOrder(contract.Symbol, 1)
        self.Debug("Call entry submitted: " + str(contract.Symbol))

    def EvaluateProfitTarget(self, slice):
        if self.held_option is None or self.exit_order is not None:
            return

        quote = self.GetCurrentQuote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("profit target")

    def EvaluateTimeStop(self):
        if self.held_option is None or self.exit_order is not None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        prior_trading_day = self.PreviousTradingDay(expiry)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration time stop")

    def HandleExpirationProcessing(self, current_date):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()

        if current_date >= expiry:
            self.no_entry_date = current_date

            if self.entry_order is not None:
                self.entry_order.Cancel("Expiration processing")
                self.entry_order = None

            if self.exit_order is None:
                self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_order is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.CancelOpenExitOrder()
        self.exit_order = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Call exit submitted: " + reason)

    def OnOrderEvent(self, order_event):
        if (
            self.entry_order is not None
            and order_event.OrderId == self.entry_order.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_option)
                    + " at "
                    + str(self.entry_price)
                )
                self.entry_order = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Call entry canceled or invalid.")
                self.entry_order = None
                self.held_option = None
                self.entry_price = None

        if (
            self.exit_order is not None
            and order_event.OrderId == self.exit_order.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call exit filled.")
                self.exit_order = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order = None

        message = str(order_event.Message or "").lower()
        if "exercise" in message or "assign" in message:
            self.Debug("Unexpected exercise or assignment detected.")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating.")
            self.MarketOrder(self.spy.Symbol, -holding.Quantity)

    def HasOptionHolding(self):
        return (
            self.held_option is not None
            and self.Portfolio[self.held_option].Quantity != 0
        )

    def CancelOpenExitOrder(self):
        if self.exit_order is not None:
            status = self.exit_order.Status
            if status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order.Cancel("Replacing exit order")
            self.exit_order = None

    def GetCurrentOptionChain(self, slice):
        try:
            chains = slice.OptionChains
            try:
                chain = chains.get(self.option.Symbol)
                if chain is not None:
                    return chain
            except Exception:
                pass

            for item in chains:
                candidate = getattr(item, "Value", item)
                symbol = getattr(item, "Key", None)
                if symbol == self.option.Symbol:
                    return candidate
                if getattr(candidate, "Symbol", None) == self.option.Symbol:
                    return candidate
        except Exception:
            return None

        return None

    def GetCurrentQuote(self, slice, symbol):
        try:
            quote = slice.QuoteBars.get(symbol)
            if quote is None:
                return None

            bid = quote.Bid.Close
            ask = quote.Ask.Close

            if bid is None or ask is None:
                return None

            bid = float(bid)
            ask = float(ask)

            if bid <= 0 or ask <= 0:
                return None

            return bid, ask
        except Exception:
            return None

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

