        )
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.current_bucket_date = None
        self.current_bucket_end_minute = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_option = None
        self.entry_price = None
        self.expiry_date = None
        self.exit_ticket = None
        self.expiration_blocked_date = None
        self.assignment_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        if self.held_option is not None:
            self._evaluate_option_exit(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        now = self.Time
        minute = now.hour * 60 + now.minute

        # Regular-session minute bars only.
        if minute <= 9 * 60 + 30 or minute > 16 * 60:
            return

        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_date = now.date()

        if (
            self.current_bucket_date != bucket_date
            or self.current_bucket_end_minute != bucket_end_minute
        ):
            self.current_bucket_date = bucket_date
            self.current_bucket_end_minute = bucket_end_minute
            self.current_bucket_bars = {}

        self.current_bucket_bars[minute] = bar

        if minute != bucket_end_minute:
            return

        expected_minutes = set(range(bucket_end_minute - 4, bucket_end_minute + 1))
        if set(self.current_bucket_bars.keys()) != expected_minutes:
            self.current_bucket_bars = {}
            return

        consolidated_close = bar.Close
        self.current_bucket_bars = {}

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(consolidated_close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        if bucket_end_minute < 9 * 60 + 45 or bucket_end_minute > 14 * 60 + 30:
            return

        if self.expiration_blocked_date == self.Time.date():
            return

        if self.held_option is not None or self._entry_order_open():
            return

        self._try_enter(slice, consolidated_close)

    def _try_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no eligible expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        threshold = 1.01 * spy_price

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.expiry_date = selected.Expiry.date()
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
