        if self.expiry_date is not None and current_date >= self.expiry_date:
            self.expiration_blocked_date = current_date
            self._submit_exit("Expiration-day liquidation")
            return

        # Time stop at 15:45 on the trading day immediately preceding expiry.
        if (
            self.expiry_date is not None
            and current_date == self.expiry_date - timedelta(days=1)
            and self.Time.hour >= 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self._exit_order_open():
