        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_option),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None or self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_option}; reason={reason}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if not self._ticket_open(self.assignment_liquidation_ticket):
            self.Debug(
                f"Unexpected SPY equity position detected: "
                f"quantity={quantity}; liquidating."
            )
            self.assignment_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiry_date = order_event.Symbol.ID.Date.date()
                self.Debug(
                    f"Entry filled: {self.held_option}; "
                    f"price={self.entry_price}"
                )

            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None
                self.entry_symbol = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.expiry_date = None
                self.entry_symbol = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

        if (
            self.assignment_liquidation_ticket is not None
            and order_event.OrderId == self.assignment_liquidation_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.assignment_liquidation_ticket = None

    def _entry_order_open(self):
        return self._ticket_open(self.entry_ticket)

    def _exit_order_open(self):
        return self._ticket_open(self.exit_ticket)

    @staticmethod
    def _ticket_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

