from AlgorithmImports import *


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast_closes = []
        self.slow_closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_date = None
        self.bucket_closes = []
        self.bucket_valid = True

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entries_date = None
        self.equity_cleanup_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self.held_symbol is not None:
            self._evaluate_exit(slice)

        signal = self._update_five_minute_bar(slice)

        if signal is not None:
            self._try_enter(slice, signal["close"], signal["end_time"])

    def _update_five_minute_bar(self, slice):
        if self.spy not in slice.Bars:
            return None

        bar = slice.Bars[self.spy]
        local_time = self.Time.replace(second=0, microsecond=0)
        current_date = local_time.date()

        if local_time.hour < 9 or (local_time.hour == 9 and local_time.minute < 30):
            return None
        if local_time.hour >= 16:
            return None

        minutes_from_open = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        bucket_minute = 9 * 60 + 30 + (minutes_from_open // 5) * 5
        bucket_start = local_time.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60
        )

        signal = None

        if self.bucket_start is None:
            self._start_bucket(bucket_start, current_date)
        elif bucket_start != self.bucket_start or current_date != self.bucket_date:
            signal = self._finish_bucket()
            self._start_bucket(bucket_start, current_date)

        expected_minute = self.bucket_start + timedelta(minutes=len(self.bucket_closes))

        if local_time != expected_minute:
            self.bucket_valid = False

        if len(self.bucket_closes) < 5:
            self.bucket_closes.append(float(bar.Close))

        if len(self.bucket_closes) == 5:
            completed = self._finish_bucket()
            if completed is not None:
                signal = completed

        return signal

    def _start_bucket(self, bucket_start, bucket_date):
        self.bucket_start = bucket_start
        self.bucket_date = bucket_date
        self.bucket_closes = []
        self.bucket_valid = True

    def _finish_bucket(self):
        if self.bucket_start is None:
            return None

        closes = self.bucket_closes
        valid = self.bucket_valid and len(closes) == 5
        end_time = self.bucket_start + timedelta(minutes=5)

        self.bucket_start = None
        self.bucket_date = None
        self.bucket_closes = []
        self.bucket_valid = True

        if not valid:
            return None

        close = closes[-1]
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) > self.fast_period:
            self.fast_closes.pop(0)
        if len(self.slow_closes) > self.slow_period:
            self.slow_closes.pop(0)

        current_fast = None
        current_slow = None

        if len(self.fast_closes) == self.fast_period:
            current_fast = sum(self.fast_closes) / self.fast_period
        if len(self.slow_closes) == self.slow_period:
            current_slow = sum(self.slow_closes) / self.slow_period

        signal = None

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        ):
            end_local = end_time
            if (
                end_local.hour > 9
                or (end_local.hour == 9 and end_local.minute >= 45)
            ) and (
                end_local.hour < 14
                or (end_local.hour == 14 and end_local.minute <= 30)
            ):
                signal = {
                    "close": close,
                    "end_time": end_time
                }

        if current_fast is not None and current_slow is not None:
            self.previous_fast = current_fast
            self.previous_slow = current_slow

        return signal

    def _try_enter(self, slice: Slice, spy_price, bar_end_time):
        if self.no_entries_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if spy_price <= 0 or not slice.OptionChains:
            self.Debug("Skipped call selection: no current option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible = []

        for chain in slice.OptionChains:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        earliest_expiry = min(c.Expiry.date() for c in eligible)
        candidates = [
            c for c in eligible
            if c.Expiry.date() == earliest_expiry
        ]
        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        local_time = self.Time
        contract = self.Securities[self.held_symbol]
        expiry_date = contract.Expiry.date()

        if self._is_time_stop_day(expiry_date, local_time.date()):
            if local_time.hour > 15 or (
                local_time.hour == 15 and local_time.minute >= 45
            ):
                self._submit_exit("time stop")
                return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(
            "Exit submitted ({}): {}".format(reason, self.held_symbol)
        )

    def _handle_expiration_processing(self):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Expiry.date()
        if self.Time.date() >= expiry_date:
            self.no_entries_date = self.Time.date()
