from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.held_expiration = None
        self.entry_price = None
        self.expiration_stop_date = None
        self.expiration_processing = False
        self.blocked_entry_date = None
        self.assignment_liquidation_ticket = None

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

    def OnData(self, data: Slice):
        self.current_slice = data

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()
        self.HandleScheduledExit(data)
        self.HandleProfitTarget(data)

        if data.Bars.ContainsKey(self.spy):
            self.consolidator.Update(data.Bars[self.spy])

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        bar_time = bar.EndTime.time()

        self.fast_closes.append(float(bar.Close))
        self.slow_closes.append(float(bar.Close))

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_crossover:
            return

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self.IsEntryOrderOpen():
            return

        self.TryEnterCall()

    def TryEnterCall(self):
        if self.current_slice is None:
            return

        chain = self.current_slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiration = expirations[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected_contract = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected_contract.Symbol, 1)

    def HandleProfitTarget(self, data: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.IsExitOrderOpen():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = chain.Contracts.get(self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -self.Portfolio[self.held_symbol].Quantity
            )
            self.Debug(
                "Profit target exit submitted for {0}; midpoint={1:.2f}".format(
                    self.held_symbol, midpoint
                )
            )

    def HandleScheduledExit(self, data: Slice):
        if self.held_symbol is None or self.held_expiration is None:
            return

        if self.expiration_stop_date != self.Time.date():
            return

        if self.Time.hour != 15 or self.Time.minute != 45:
            return

        if self.IsExitOrderOpen():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(
            "Time-stop exit submitted for {0} before expiration.".format(
                self.held_symbol
            )
        )

    def HandleExpirationProcessing(self):
        if self.held_symbol is None or self.held_expiration is None:
            return

        if self.Time.date() < self.held_expiration.date():
            return

        if not self.expiration_processing:
            self.expiration_processing = True
            self.blocked_entry_date = self.Time.date()
            self.Debug(
                "Unexpected expiration processing for {0}; liquidation submitted.".format(
                    self.held_symbol
                )
            )

        if not self.IsExitOrderOpen():
            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)

    def HandleUnexpectedEquityPosition(self):
        if self.assignment_liquidation_ticket is not None:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.blocked_entry_date = self.Time.date()
        self.assignment_liquidation_ticket = self.MarketOrder(self.spy, -quantity)
        self.Debug(
            "Unexpected exercise or assignment created SPY equity; liquidation submitted."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.held_expiration = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date

                self.expiration_stop_date = self.PreviousTradingDay(
                    self.held_expiration.date()
                )

                self.Debug(
                    "Entered 1 call: {0}, fill={1:.2f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
                self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exited call: {0}, fill={1:.2f}".format(
                        order_event.Symbol, float(order_event.FillPrice)
                    )
                )
                self.ClearPositionState()
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.assignment_liquidation_ticket is not None and
            order_event.OrderId == self.assignment_liquidation_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY equity position liquidated.")
            self.assignment_liquidation_ticket = None

        if (
            getattr(order_event, "OrderType", None) == OrderType.OptionExercise
            or getattr(order_event, "IsAssignment", False)
        ):
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment event received.")

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def IsEntryOrderOpen(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def IsExitOrderOpen(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def CancelOpenExitOrder(self):
        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Profit target reached; canceling prior exit order.")

    def ClearPositionState(self):
        self.held_symbol = None
        self.held_expiration = None
        self.entry_price = None
        self.expiration_stop_date = None
        self.expiration_processing = False

