        current_date = self.Time.date()

        # Immediately remove any unexpected SPY equity position.
        equity_holding = self.Portfolio[self.spy_symbol]
        if equity_holding.Invested:
            if self.equity_liquidation_order_id is None:
                self.Debug("Unexpected SPY exercise/assignment; liquidating equity.")
                ticket = self.MarketOrder(
                    self.spy_symbol, -equity_holding.Quantity
                )
                self.equity_liquidation_order_id = ticket.OrderId

        # Never intentionally hold an option into expiration.
        if (
            self.held_symbol is not None
            and current_date >= self.held_symbol.ID.Date.date()
        ):
            self.expiry_block_date = current_date
            self._cancel_open_exit_order()
            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0 and self.exit_order_id is None:
                self.Debug("Expiration processing; liquidating held call.")
                ticket = self.MarketOrder(self.held_symbol, -quantity)
                self.exit_order_id = ticket.OrderId
            return

        if self.held_symbol is not None:
            self._evaluate_profit_target(slice)
            self._evaluate_time_stop()

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy_symbol:
            return

        bar_time = bar.EndTime.time()
        if bar_time < time(9, 30) or bar_time > time(16, 0):
            return

        self.closes.append(float(bar.Close))

        if len(self.closes) < 21:
            return

        previous_fast = sum(self.closes[-6:-1]) / 5.0
        previous_slow = sum(self.closes[-21:-1]) / 20.0
        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        bullish_cross = (
            previous_fast <= previous_slow and current_fast > current_slow
        )
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter_call(float(bar.Close))

    def _try_enter_call(self, spy_price: float):
        current_date = self.Time.date()

        if current_date == self.expiry_block_date:
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        chains = list(self.CurrentSlice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        eligible_expiries = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= current_date + timedelta(days=7):
                    eligible_expiries.append(expiry_date)

        if not eligible_expiries:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = min(eligible_expiries)
        minimum_strike = spy_price * 1.01
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Expiry.date() == selected_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol)),
        )

