            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0:
                self.Debug("Profit target reached; liquidating held call.")
                ticket = self.MarketOrder(self.held_symbol, -quantity)
                self.exit_order_id = ticket.OrderId

    def _evaluate_time_stop(self):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        stop_date = self._previous_trading_day(expiry_date)

        if self.Time.date() == stop_date and self.Time.time() >= time(15, 45):
            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0:
                self.Debug("Expiration time stop reached; liquidating held call.")
                ticket = self.MarketOrder(self.held_symbol, -quantity)
                self.exit_order_id = ticket.OrderId

    def _previous_trading_day(self, expiry_date: date) -> date:
        candidate = expiry_date - timedelta(days=1)
        while not self._is_trading_day(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def _is_trading_day(self, trading_date: date) -> bool:
        dt = datetime(
            trading_date.year, trading_date.month, trading_date.day
        )
        return self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(dt)

    def _entry_order_is_open(self) -> bool:
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    def _cancel_open_exit_order(self):
        if self.exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        ):
            ticket.Cancel("Canceled by replacement liquidation request.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    "Call entry filled: {0} at {1}.".format(
                        self.held_symbol, self.entry_price
                    )
                )

            elif order_event.OrderId == self.exit_order_id:
                self.Debug("Call exit filled: {0}.".format(order_event.Symbol))
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.OrderId == self.equity_liquidation_order_id:
                self.equity_liquidation_order_id = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            if order_event.OrderId == self.entry_order_id:
                self.Debug("Call entry order canceled or invalid.")
                self.entry_order_id = None
            elif order_event.OrderId == self.exit_order_id:
                self.Debug("Call exit order canceled or invalid.")
                self.exit_order_id = None

