    def GetFiveMinuteBucketStart(self, timestamp):
        if timestamp.date() != self.Time.date():
            return None

        session_start = timestamp.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        session_end = timestamp.replace(
            hour=16, minute=0, second=0, microsecond=0
        )

        if timestamp < session_start or timestamp >= session_end:
            return None

        elapsed_minutes = int((timestamp - session_start).total_seconds() // 60)
        bucket_minutes = (elapsed_minutes // 5) * 5
        return session_start + timedelta(minutes=bucket_minutes)

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

