from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.expiration_block_date = None
        self.spy_liquidation_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.held_symbol is not None:
            if self.expiration_date is not None:
                if current_date >= self.expiration_date:
                    self.expiration_block_date = current_date
                    self.SubmitExit("expiration")

                elif self.Time.time().hour == 15 and self.Time.time().minute == 45:
                    previous_trading_day = self.GetPreviousTradingDay(
                        self.expiration_date
                    )
                    if current_date == previous_trading_day:
                        self.SubmitExit("time stop")

                if self.exit_ticket is None:
                    quote = slice.QuoteBars.get(self.held_symbol)
                    if quote is not None and quote.Bid is not None and quote.Ask is not None:
                        bid = quote.Bid.Close
                        ask = quote.Ask.Close
                        if bid > 0 and ask > 0:
                            midpoint = (bid + ask) / 2.0
                            if midpoint >= 1.5 * self.entry_price:
                                self.SubmitExit("profit target")

        spy_holding = self.Portfolio[self.spy.Symbol]
        if spy_holding.Quantity != 0:
            if self.spy_liquidation_ticket is None:
                self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
                self.spy_liquidation_ticket = self.MarketOrder(
                    self.spy.Symbol, -spy_holding.Quantity
                )

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        end_time = bar.EndTime
        end_date = end_time.date()
        end_clock = end_time.time()

        if end_clock < datetime.strptime("09:35", "%H:%M").time():
            return
        if end_clock > datetime.strptime("16:00", "%H:%M").time():
            return
        if end_clock.minute % 5 != 0 or end_clock.second != 0:
            return

        self.fast_window.append(float(bar.Close))
        self.slow_window.append(float(bar.Close))

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        current_fast = sum(list(self.fast_window)[-5:]) / 5.0
        current_slow = sum(self.slow_window) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if (
            bullish_cross
            and eligible_start <= end_clock <= eligible_end
            and self.expiration_block_date != end_date
            and self.held_symbol is None
            and not self.IsEntryOrderOpen()
        ):
            self.TryEnterFromCurrentSlice()

    def TryEnterFromCurrentSlice(self):
        slice = self.CurrentSlice

        if self.spy.Symbol not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = float(slice.Bars[self.spy.Symbol].Close)
        minimum_expiry = self.Time.date() + timedelta(days=7)

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible_contracts = []
        expiration_dates = set()

        for contract in chain:
            contract_expiry = contract.Expiry.date()

            if contract_expiry >= minimum_expiry:
                expiration_dates.add(contract_expiry)
                if (
                    contract.Right == OptionRight.Call
                    and contract.Strike >= 1.01 * spy_price
                ):
                    eligible_contracts.append(contract)

        if not expiration_dates:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = min(expiration_dates)
        candidates = [
            contract
            for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol)),
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiration {} strike {:.2f}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity

        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted: {}".format(reason))

    def GetPreviousTradingDay(self, date_value):
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        previous = exchange_hours.GetPreviousTradingDay(
            datetime(date_value.year, date_value.month, date_value.day)
        )
        return previous.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = self.held_symbol.ID.Date.date()
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
                self.entry_ticket = None

            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self.held_symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None

            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

        if (
            self.spy_liquidation_ticket is not None
            and order_event.OrderId == self.spy_liquidation_ticket.OrderId
            and order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
        ):
            self.spy_liquidation_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment received.")
        spy_holding = self.Portfolio[self.spy.Symbol]
        if spy_holding.Quantity != 0 and self.spy_liquidation_ticket is None:
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy.Symbol, -spy_holding.Quantity
            )

