from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda u: u.Strikes(-100, 100).Expiration(0, 730))
        self.spy_option = option.Symbol

        self.closes = deque(maxlen=20)
        self.current_bucket_start = None
        self.current_bucket_closes = []
        self.current_bucket_valid = True
        self.last_minute = None

        self.current_chain = None
        self.current_spy_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        today = self.Time.date()
        self.current_chain = None

        if self.spy in data.Bars:
            spy_bar = data.Bars[self.spy]
            self.current_spy_price = spy_bar.Close
            self._update_five_minute_bar(spy_bar)

        if data.OptionChains:
            for chain in data.OptionChains.Values:
                if chain.Symbol == self.spy_option:
                    self.current_chain = chain
                    break

        self._handle_unexpected_equity_position(today)
        self._handle_expiration_processing(today)
        self._evaluate_option_exit(data, today)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        bar_time = minute_bar.Time
        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
            self.current_bucket_closes = []
            self.current_bucket_valid = True
        elif bucket_start != self.current_bucket_start:
            self._process_completed_bucket()
            self.current_bucket_start = bucket_start
            self.current_bucket_closes = []
            self.current_bucket_valid = True
        elif self.last_minute is not None and bar_time != self.last_minute + timedelta(minutes=1):
            self.current_bucket_valid = False

        if bar_time.hour == 9 and bar_time.minute < 30:
            self.last_minute = bar_time
            return

        if bar_time.hour > 15 or (bar_time.hour == 15 and bar_time.minute >= 60):
            self.last_minute = bar_time
            return

        if bar_time.hour == 9 and bar_time.minute < 30:
            self.last_minute = bar_time
            return

        self.current_bucket_closes.append(minute_bar.Close)
        self.last_minute = bar_time

    def _process_completed_bucket(self):
        if not self.current_bucket_valid or len(self.current_bucket_closes) != 5:
            return

        bar_end = self.current_bucket_start + timedelta(minutes=5)

        if not (time(9, 30) <= self.current_bucket_start.time() < time(16, 0)):
            return

        previous = list(self.closes)

        if len(previous) >= 20:
            previous_fast = sum(previous[-5:]) / 5.0
            previous_slow = sum(previous[-20:]) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(self.current_bucket_closes[-1])
        current = list(self.closes)

        if len(current) < 20:
            return

        current_fast = sum(current[-5:]) / 5.0
        current_slow = sum(current[-20:]) / 20.0

        bullish_cross = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_cross and time(9, 45) <= bar_end.time() <= time(14, 30):
            self._try_enter_call(bar_end.date())

    def _try_enter_call(self, signal_date):
        if self.no_entry_date == signal_date:
            return

        if self.entry_ticket is not None and not self._order_done(self.entry_ticket):
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.current_chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        if self.current_spy_price is None or self.current_spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry = signal_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in self.current_chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * self.current_spy_price

        candidates = [
            contract for contract in self.current_chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_option_exit(self, data: Slice, today):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and not self._order_done(self.exit_ticket):
            return

        if self.held_expiry is not None:
            previous_trading_day = self._previous_trading_day(self.held_expiry)
            if today == previous_trading_day and self.Time.time() >= time(15, 45):
                self._submit_exit("expiration time stop")
                return

        if self.held_symbol not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._order_done(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by " + reason)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Option exit submitted: {0}".format(reason))

    def _handle_expiration_processing(self, today):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if today >= self.held_expiry:
            self.no_entry_date = today
            if self.Portfolio[self.held_symbol].Invested:
                self._submit_exit("expiration protection")
                self.Debug("Expiration protection activated.")

    def _handle_unexpected_equity_position(self, today):
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = today
            quantity = self.Portfolio[self.spy].Quantity
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise or assignment")
            self.Debug(
                "Unexpected exercise or assignment handled; SPY equity liquidated."
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self.held_symbol, self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Call exit filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.held_expiry = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def _order_done(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

