                self._try_enter(slice, signal_end)

        self._evaluate_profit_target(slice)

    def _update_five_minute_bar(self, bar):
        bar_time = self._local_time(bar.Time)
        minute = bar_time.minute

        if not (time(9, 30) <= bar_time.time() < time(16, 0)):
            return None

        bucket_start = bar_time.replace(
            minute=(minute // 5) * 5,
            second=0,
            microsecond=0
        )

