        if minute_offset < 0 or minute_offset > 4:
            return None

        self.bucket_bars[minute_offset] = bar

        if minute_offset != 4:
            return None

        if set(self.bucket_bars.keys()) != {0, 1, 2, 3, 4}:
            self.bucket_bars = {}
            return None

        bars = [self.bucket_bars[i] for i in range(5)]
        close = bars[-1].Close

