        signal_end = self.bucket_start + timedelta(minutes=5)
        bullish = (
            current_fast is not None and
            current_slow is not None and
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow and
            time(9, 45) <= signal_end.time() <= time(14, 30)
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.bucket_bars = {}

        return signal_end if bullish else None

    def _try_enter(self, slice, bar_end):
        today = self._local_time(self.Time).date()

        if self.no_entry_date == today:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if self.held_option is not None:
