            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.held_option = selected.Symbol
        self.expiration_date = expiration
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            self.held_option,
            1,
            tag="Bullish five-minute SMA crossover"
        )
        self.entry_order_id = self.entry_ticket.OrderId

    def _evaluate_profit_target(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        try:
            if self.Portfolio[self.held_option].Quantity <= 0:
                return
        except Exception:
            return

        contract = None
        try:
            chain = slice.OptionChains.get(self.spy_option.Symbol)
            if chain is not None:
                contract = chain.Contracts.get(self.held_option)
        except Exception:
            contract = None

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_open_exit()
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -self.Portfolio[self.held_option].Quantity,
                tag="50 percent profit target"
            )
            self.Debug("Exit submitted: 50 percent profit target.")

    def _handle_expiration_and_time_stop(self, now):
        if self.held_option is None or self.expiration_date is None:
            return

        try:
            quantity = self.Portfolio[self.held_option].Quantity
        except Exception:
            quantity = 0

        if quantity <= 0:
            return

        today = now.date()

        if today >= self.expiration_date:
            self.no_entry_date = today
            self._submit_liquidation("Expiration protection")
            return

        prior_trading_day = self._previous_trading_day(self.expiration_date)

        if today == prior_trading_day and now.time() >= time(15, 45):
            self._submit_liquidation("Expiration time stop")

    def _submit_liquidation(self, tag):
        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag=tag
            )
            self.Debug("Exit submitted: " + tag + ".")

    def _handle_unexpected_spy_position(self, today):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity != 0:
            self.no_entry_date = today
            self.Liquidate(
                self.spy.Symbol,
                tag="Unexpected exercise or assignment"
            )
            self.Debug("Unexpected SPY exercise or assignment handled.")

    def _cancel_open_exit(self):
        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority liquidation")

    def OnOrderEvent(self, order_event: OrderEvent):
        order_type_text = str(order_event.OrderType).lower()
        assignment = bool(getattr(order_event, "IsAssignment", False))

        if assignment or "exercise" in order_type_text or "assignment" in order_type_text:
            self.no_entry_date = self._local_time(self.Time).date()
            self.Debug("Unexpected exercise or assignment order event handled.")

        if (
            self.entry_order_id is not None and
            order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: " +
                    str(self.held_option) +
                    " at " +
                    str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_order_id = None
                self.entry_ticket = None
                self.held_option = None
                self.expiration_date = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option position liquidated.")
                self.exit_ticket = None
                self.entry_price = None
                self.held_option = None
                self.expiration_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _local_time(value):
        if value.tzinfo is not None:
            value = value.replace(tzinfo=None)
        return value

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

